@startuml

class Customer {
  +name : string
  +surname : string
  +email : string
  +telephone : string
  +homeAddress : string
}

class Order {
  +totalCost : double
  +estimatedDeliveryTime : time
  +status : string
}

class Dish {
  +preparationTime : int
}

Customer "1" -- "*" Order : makes
Order "*" -- "1..*" Dish : contains

@enduml

